import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/constants.dart';
import '../../../core/providers.dart';
import '../../../core/theme/app_theme.dart';
import '../../../core/widgets/common.dart';
import '../../billing/domain/billing_calculator.dart';

class InventoryScreen extends ConsumerStatefulWidget{const InventoryScreen({super.key});@override ConsumerState<InventoryScreen> createState()=>_InventoryScreenState();}
class _InventoryScreenState extends ConsumerState<InventoryScreen>{final fields=<String,TextEditingController>{};bool busy=false;@override void dispose(){for(final c in fields.values)c.dispose();super.dispose();}
@override Widget build(BuildContext context){final inventory=ref.watch(inventoryProvider).asData?.value??const <Map<String,dynamic>>[];final map={for(final x in inventory)'${x['item']}':x};final bills=ref.watch(hydratedBillsProvider);final rented=<String,int>{for(final s in materialCatalog)s.key:0};final rentedWood=<String,Map<String,int>>{for(final s in woodCatalog)s.key:{}};for(final b in bills.where((b)=>b['status']!='closed')){for(final s in materialCatalog)rented[s.key]=rented[s.key]!+(((b['balance_qty'] as Map)[s.key] as num?)?.toInt()??0);for(final s in woodCatalog){final w=(b['balance_wood'] as Map)[s.key] as Map? ?? {};for(final e in w.entries){rentedWood[s.key]![e.key]=(rentedWood[s.key]![e.key]??0)+(e.value as num).toInt();}}}return Scaffold(appBar:AppBar(title:const Text('Inventory')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Material stock',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),const SizedBox(height:12),...materialCatalog.map((s){final stock=((map[s.key]?['stock_qty'] as num?)?.toInt()??0);final ctrl=fields.putIfAbsent(s.key,()=>TextEditingController(text:'$stock'));return Card(margin:const EdgeInsets.only(bottom:9),child:Padding(padding:const EdgeInsets.all(14),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s.label,style:const TextStyle(fontWeight:FontWeight.w700)),Text('${rented[s.key]} on rent · ${stock-rented[s.key]!} available',style:TextStyle(color:AppPalette.of(context).muted,fontSize:12))])),SizedBox(width:96,child:TextField(controller:ctrl,keyboardType:TextInputType.number,textAlign:TextAlign.end,decoration:const InputDecoration(labelText:'Stock')))])));}),const SectionTitle('Wood stock'),...woodCatalog.map((s){final raw=map[s.key]?['stock_map'] as Map? ?? {};final text=woodToText(Map<String,int>.from(raw.map((k,v)=>MapEntry('$k',(v as num).toInt()))));final ctrl=fields.putIfAbsent(s.key,()=>TextEditingController(text:text=='0'?'':text));final out=woodToText(rentedWood[s.key]);return Card(margin:const EdgeInsets.only(bottom:9),child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s.label,style:const TextStyle(fontWeight:FontWeight.w700)),Text('On rent: $out',style:TextStyle(color:AppPalette.of(context).muted,fontSize:12)),const SizedBox(height:8),TextField(controller:ctrl,decoration:const InputDecoration(labelText:'Total sizes and pieces',hintText:'8×20+10×10'))])));}),const SizedBox(height:12),FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save_outlined),label:Text(busy?'Saving…':'Save inventory'))]));}
Future<void> save()async{setState(()=>busy=true);try{final repo=ref.read(billingRepositoryProvider);for(final s in materialCatalog){await repo.put('inventory',{'item':s.key,'stock_qty':(int.tryParse(fields[s.key]!.text)??0).clamp(0,100000000)});}for(final s in woodCatalog){await repo.put('inventory',{'item':s.key,'stock_map':parseWoodSizes(fields[s.key]!.text)});}if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Inventory saved')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Save failed: $e')));}finally{if(mounted)setState(()=>busy=false);}}
}
